{
  "title": "A Softer Morning After Pontocho",
  "summary": "We trade the early rush for two unhurried stops, a long vegan lunch, and an evening wander where the lanterns do the talking.",
  "stops": [
    {
      "poi_id": "p12",
      "kind": "activity",
      "must_do_id": null,
      "note": "One quiet hall of a thousand faces, taken slowly. No sprinting, just looking.",
      "must_do_id": null
    },
    {
      "poi_id": "p19",
      "kind": "meal",
      "must_do_id": null,
      "note": "A long, easy vegan lunch. Shoes off, phone down, eyes up.",
      "must_do_id": null
    },
    {
      "poi_id": "p13",
      "kind": "activity",
      "must_do_id": "m3",
      "note": "The must-do stays, but later and lighter. The deer will cope without you. The lanterns won't wait.",
      "must_do_id": "m3"
    }
  ]
}
